const badgeOf=modules=>modules.some(module=>module.classification==='domain-logic')?'domain-logic':'generic';
/** Map from module path to its component and entry. */
export function registeredModules(){const map=new Map();for(const component of RUNTIME_COMPONENTS)for(const module of component.modules)map.set(module.path,{component:component.id,module});return map;}
/** The audit record the Worlds map attaches to a component's node. */
export function componentAudit(component){
 const counts={};for(const module of component.modules)counts[module.classification]=(counts[module.classification]??0)+1;
 return {component:component.id,badge:badgeOf(component.modules),counts,activityHook:!!(component.activity?.operations?.length||component.activity?.nodeIds?.length),activity:{operations:component.activity?.operations??[],nodeIds:component.activity?.nodeIds??[]},actsOn:component.actsOn??[],uiHelper:!!component.uiHelper,modules:component.modules.map(module=>({...module}))};
}
/** Totals for the map's status and the audit document. */
export function auditRuntimeComponents(){
 const modules=RUNTIME_COMPONENTS.flatMap(component=>component.modules);
 return {components:RUNTIME_COMPONENTS.length,modules:modules.length,domainComponents:RUNTIME_COMPONENTS.filter(component=>badgeOf(component.modules)==='domain-logic').length,domainModules:modules.filter(module=>module.classification==='domain-logic').length,
  silentComponents:RUNTIME_COMPONENTS.filter(component=>!(component.activity?.operations?.length||component.activity?.nodeIds?.length)).length,secretModules:modules.filter(module=>module.secret?.length).length};
}
